            # Check for payload
            try:
                col_ind = rows
                for c in range(1, cols):
                    if grid[r][c] == 7:
                        col_ind = c
                        break

                if col_ind < cols:
                    # Fill from 1 to col_ind-1 with 7
                    for c in range(1, col_ind):
                        grid[r][c] = 7
                    # Replace payload with 4
                    grid[r][col_ind] = 4
            except:
                pass
        # Check for Right Marker
        elif grid[r][cols-1] == 9:
            # Check for payload
            try:
                col_ind = -1
                for c in range(0, cols-1):
                    if grid[r][c] == 7:
                        col_ind = c
                        break

                if col_ind >= 0:
                    # Fill from col_ind+1 to cols-2 with 7
                    for c in range(col_ind+1, cols-1):
                        grid[r][c] = 7
                    # Do NOT replace payload (7 stays 7)
            except:
                pass

    return grid
